WITH base AS (SELECT id, customer_id, end_date, monthly_fee, status, LOWER(plan) plan_lower FROM subscriptions WHERE end_date BETWEEN '2025-02-22' AND '2025-07-01' AND end_date >= DATE '2023-09-10') SELECT customer_id, CASE WHEN monthly_fee >= 187 THEN 'PREMIUM' ELSE 'STANDARD' END AS monthly_fee_tier, STDDEV_SAMP(monthly_fee) AS monthly_fee_stddev, STDDEV_SAMP(monthly_fee) AS monthly_fee_stddev_2, MAX(monthly_fee) AS max_monthly_fee FROM base GROUP BY CUBE (customer_id, CASE WHEN monthly_fee >= 187 THEN 'PREMIUM' ELSE 'STANDARD' END) ORDER BY monthly_fee_tier DESC NULLS LAST
